use vstd::prelude::*;

verus! {
    // Specification for the contains_z function
    fn contains_z(s: &str) -> (result: bool)
        ensures
            result == (exists |i: nat| 0 <= i < s.len() as nat && (s.chars().nth(i as usize) == Some('z') || s.chars().nth(i as usize) == Some('Z'))),
    {
        let mut i: nat = 0;
        let len: nat = s.chars().count() as nat; // Get the character-level length of the string
        let mut found: bool = false;

        // Iterate through each character in the string
        while i < len
            invariant
                0 <= i <= len,
                found ==> (s.chars().nth(i as usize) == Some('z') || s.chars().nth(i as usize) == Some('Z')),
                result == found,
            decreases len - i,
        {
            // Check if the current character is 'z' or 'Z'
            if s.chars().nth(i as usize) == Some('z') || s.chars().nth(i as usize) == Some('Z') {
                found = true; // Set found to true if 'z' or 'Z' is found
            }
            i = i + 1; // Move to the next character
        }

        found // Return the result
    }
}

